import React, { useState, useEffect } from "react";
import "./Library.css";

const Resource = () => {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchVideos = async () => {
      try {
        const userId = localStorage.getItem("user_id"); // Get logged-in user's ID
        if (!userId) {
          console.error("No user ID found. Please log in first.");
          setLoading(false);
          return;
        }

        const response = await fetch(`http://34.55.142.231:5000/videos/${userId}`);
        const data = await response.json();
        console.log("Fetched videos:", data);
        setVideos(data);
      } catch (error) {
        console.error("Error fetching videos:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchVideos();
  }, []);

  // Handle click to show feedback
  const handleClick = (feedback) => {
    alert(feedback);
  };

  return (
    <div className="resource-section">
      <h1>Library</h1>

      <div className="resource-content">
        {loading ? (
          <p>Loading videos...</p>
        ) : videos.length === 0 ? (
          <p>No videos uploaded yet. Upload one from Dashboard!</p>
        ) : (
          <div className="video-container">
            {videos.map((video) => (
              <div key={video.video_id} className="video-card" onClick={() => handleClick(video.feedback)}>
                <div className="video-card-content">
                  <img
                    src="https://via.placeholder.com/150"
                    alt="Video Thumbnail"
                    className="video-thumbnail"
                  />
                  <h3>{video.video_filename}</h3>
                  <p>Click Read More to view AI Feedback</p>
                  <button className="read-more-btn">Read More</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Resource;
